Lemma art_tsd_tr : forall W M M' tp key tsd ctx t, art_agree W M M' ->
  art_gap W 0x145960 8 -> art_gap W (tp - 88) 8 -> art_gap W (tsd + 8 * key) 8 -> art_gap W (ctx + 152) 8 ->
